package main
import("context";"fmt";"os";"time";"github.com/jackc/pgx/v5/pgxpool")
func main(){c:=context.Background();p,e:=pgxpool.New(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close();rows,e:=p.Query(c,`select j.recording_id,j.fire_at,h.metric_version,h.coverage_pct,h.largest_gap_seconds,h.gap_over_30s_count,h.gap_over_5m_count,h.overlap_count,coalesce(h.clip_count,0) from recording_jobs j left join recording_window_health h on h.job_id=j.id where j.recording_id=$1 and j.kind='continuous_window' order by j.fire_at`,408);if e!=nil{panic(e)};defer rows.Close();for rows.Next(){var id int64;var f time.Time;var v,over30,over5,ov *int;var cov,gap *float64;var clips int;if e:=rows.Scan(&id,&f,&v,&cov,&gap,&over30,&over5,&ov,&clips);e!=nil{panic(e)};g:="?";if v!=nil&&*v==2&&cov!=nil&&gap!=nil&&over30!=nil&&over5!=nil&&ov!=nil{if *ov==0&&*cov>=99&&*gap<=120{g="A"}else if *ov==0&&*cov>=95&&*gap<=900&&*over5<=1&&*over30<=6{g="B"}else if *ov==0&&*cov>=90&&*gap<=1800&&*over5<=2{g="C"}else if clips==0||*cov==0{g="F"}else if *cov<80{g="E"}else{g="D"}};fmt.Printf("%s %s v=%v cov=%v gap=%v o30=%v o5=%v ov=%v clips=%d\n",f.UTC().Format("2006-01-02"),g,v,cov,gap,over30,over5,ov,clips)}}
